def solve(Q=750.0, H_stack=100.0, plume_rise=50.0, u=7.0, y=200.0):
    import math
    H = H_stack + plume_rise

    def sigma_y(x_km):
        return 104.0 * x_km ** 0.894

    def sigma_z(x_km):
        return 61.0 * x_km ** 0.911

    def conc(x_km):
        sy = sigma_y(x_km)
        sz = sigma_z(x_km)
        return Q / (math.pi * u * sy * sz) * math.exp(-H ** 2 / (2.0 * sz ** 2))
    x_best = None
    c_best = -1.0
    x0 = 0.01
    x_max = 100.0
    n = 200000
    dx = (x_max - x0) / n
    for i in range(n + 1):
        xi = x0 + i * dx
        ci = conc(xi)
        if ci > c_best:
            c_best = ci
            x_best = xi
    lo = max(0.001, x_best - dx)
    hi = x_best + dx
    for _ in range(100):
        m1 = lo + (hi - lo) / 3.0
        m2 = hi - (hi - lo) / 3.0
        if conc(m1) < conc(m2):
            lo = m1
        else:
            hi = m2
    x_best = (lo + hi) / 2.0
    c_best_ug = conc(x_best) * 1000000.0
    return {'1': {'value': c_best_ug, 'unit': 'μg/m^3'}, '2': {'value': x_best, 'unit': 'km'}}

