def solve(w1_pct=33.0, d1_um=1.0, w2_pct=33.0, d2_um=5.0, w3_pct=34.0, d3_um=10.0, dcut_um=5.0, n_cyclones=2):
    dcut_m = dcut_um * 1e-06

    def single_cyclone_eff(d_um):
        d_m = d_um * 1e-06
        return 1.0 / (1.0 + (dcut_m / d_m) ** 2)

    def series_eff(d_um):
        eta = single_cyclone_eff(d_um)
        return 1.0 - (1.0 - eta) ** n_cyclones
    total_weight_pct = w1_pct + w2_pct + w3_pct
    collected_pct = w1_pct * series_eff(d1_um) + w2_pct * series_eff(d2_um) + w3_pct * series_eff(d3_um)
    fraction_pct = collected_pct / total_weight_pct * 100.0
    return {'1': {'value': fraction_pct, 'unit': '%'}}

