def solve(stack_height=300.0, plume_rise=100.0, runway_elevation_above_smelter=200.0, Q=5000.0, u=3.0, x=5000.0, C_limit=500.0):
    import math
    H = stack_height + plume_rise
    x_km = x / 1000.0
    sigma_y = 104.0 * x_km ** 0.894
    sigma_z = 61.0 * x_km ** 0.911
    C_lim = C_limit * 1e-06
    A = Q / (2.0 * math.pi * u * sigma_y * sigma_z)

    def conc_above_smelter_datum(z):
        t1 = math.exp(-(z - H) ** 2 / (2.0 * sigma_z ** 2))
        t2 = math.exp(-(z + H) ** 2 / (2.0 * sigma_z ** 2))
        return A * (t1 + t2)
    z_low = H
    z_high = H + 50.0 * sigma_z
    if conc_above_smelter_datum(z_low) < C_lim:
        z_solution_smelter_datum = H
    else:
        for _ in range(200):
            z_mid = 0.5 * (z_low + z_high)
            if conc_above_smelter_datum(z_mid) > C_lim:
                z_low = z_mid
            else:
                z_high = z_mid
        z_solution_smelter_datum = 0.5 * (z_low + z_high)
    altitude_above_runway = z_solution_smelter_datum - runway_elevation_above_smelter
    return {'1': {'value': altitude_above_runway, 'unit': 'm'}}

