def solve(r_low=0.8, r_high=0.9, U10=10.0, plate_tilt_from_horizontal_deg=60.0):
    import math

    def dFdr(r, U10):
        B = (0.38 - math.log10(r)) / 0.65
        term = (1.0 + 0.057 * r ** 1.05) * 10.0 ** (1.19 * math.exp(-B * B))
        val = 1.373 * U10 ** 3.41 * r ** (-3.0) * term
        return val
    n = 1000
    h = (r_high - r_low) / n
    total = 0.0
    for i in range(n + 1):
        r = r_low + i * h
        f = dFdr(r, U10)
        if i == 0 or i == n:
            w = 1.0
        elif i % 2 == 1:
            w = 4.0
        else:
            w = 2.0
        total += w * f
    integral = total * h / 3.0
    flux_cm2 = integral / 10000.0
    return {'1': {'value': flux_cm2, 'unit': 'particles cm^-2 s^-1'}}

