def solve(d1_um=0.001, d2_um=0.1, d3_um=1.0, d4_um=10.0, d5_um=100.0, pressure_atm=0.1, tilt_deg=60.0, temperature_K=298.15, g=9.81, rho_p=1000.0, mu=1.81e-05, M_air=0.02897, R=8.314462618, P0=101325.0, lambda_coeff=0.499, cc_a=1.257, cc_b=0.4, cc_c=1.1):
    import math
    P = pressure_atm * P0
    rho_air = P * M_air / (R * temperature_K)
    mean_speed_factor = math.sqrt(8.0 * M_air / (math.pi * R * temperature_K))
    lam = mu / (lambda_coeff * P * mean_speed_factor)

    def cunningham(dp):
        kn = 2.0 * lam / dp
        return 1.0 + kn * (cc_a + cc_b * math.exp(-cc_c / kn))

    def vertical_terminal_velocity(dp_um):
        dp = dp_um * 1e-06
        Cc = cunningham(dp)
        return dp ** 2 * (rho_p - rho_air) * g * Cc / (18.0 * mu)
    normal_projection = math.cos(math.radians(tilt_deg))
    diameters = [d1_um, d2_um, d3_um, d4_um, d5_um]
    results = {}
    for i, d in enumerate(diameters, start=1):
        vt_normal = vertical_terminal_velocity(d) * normal_projection
        results[str(i)] = {'value': vt_normal, 'unit': 'm/s'}
    return results

