    def A(z, z0):
        return math.log(z / z0) + beta * (z - z0) / L

    def f(z0):
        return M2 * A(z1, z0) - M1 * A(z2, z0)
    lo = 1e-12
    hi = min(z1, z2) * (1.0 - 1e-12)
    flo = f(lo)
    fhi = f(hi)
    if flo * fhi > 0:
        raise ValueError('No bracketed physical root for z0 below the lowest measurement height')
    for _ in range(200):
        mid = 0.5 * (lo + hi)
        fm = f(mid)
        if flo * fm <= 0:
            hi = mid
            fhi = fm
        else:
            lo = mid
            flo = fm
    z0 = 0.5 * (lo + hi)
    return {'1': {'value': z0, 'unit': 'm'}}

