def solve(o3_mixing_ratio_ppb=50.0, no2_mixing_ratio_ppb=50.0, altitudes_km=(0.0, 5.0, 10.0)):
    import math
    k_B = 1.380649e-23
    A = 1.2e-13
    Ea_over_R = 2450.0
    atm_data = {0.0: (101325.0, 288.15), 5.0: (54020.0, 255.65), 10.0: (26500.0, 223.15)}
    x_o3 = o3_mixing_ratio_ppb * 1e-09
    x_no2 = no2_mixing_ratio_ppb * 1e-09
    results = {}
    for i, z in enumerate(altitudes_km, start=1):
        P, T = atm_data[z]
        n_air_cm3 = P / (k_B * T) * 1e-06
        o3_0 = x_o3 * n_air_cm3
        no2_0 = x_no2 * n_air_cm3
        k = A * math.exp(-Ea_over_R / T)
        no2_target = no2_0 / math.e
        delta = o3_0 - no2_0
        if abs(delta) < 1e-30:
            tau = (math.e - 1.0) / (k * no2_0)
        else:
            o3_target = no2_target + delta
            if o3_target <= 0.0:
                tau = float('inf')
            else:
                tau = (math.log(no2_0 / o3_0) - math.log(no2_target / o3_target)) / (k * delta)
        results[str(i)] = {'value': tau, 'unit': 's'}
    return results

