    bands = [(lambda1_min_um, lambda1_max_um, F_lambda1_W_m2_um), (lambda2_min_um, lambda2_max_um, F_lambda2_W_m2_um), (lambda3_min_um, lambda3_max_um, F_lambda3_W_m2_um)]
    F_total = 0.0
    F_absorbed = 0.0
    for lmin_um, lmax_um, Fl_W_m2_um in bands:
        F_total += Fl_W_m2_um * (lmax_um - lmin_um)
        below_min_um = lmin_um
        below_max_um = min(lmax_um, lambda_abs_threshold_um)
        if below_max_um > below_min_um:
            F_absorbed += Fl_W_m2_um * (below_max_um - below_min_um) * alpha_below
        above_min_um = max(lmin_um, lambda_abs_threshold_um)
        above_max_um = lmax_um
        if above_max_um > above_min_um:
            F_absorbed += Fl_W_m2_um * (above_max_um - above_min_um) * alpha_above
    F_reflected = F_total - F_absorbed
